INSERT INTO manga VALUES(1,'solo-leveling','Yolg''izlikda daraja ko''tarish','나 혼자만 레벨업 (Solo Leveling)','Eng kuchsiz E-darajali ovchining cheksiz darajalanish siri.','https://images.unsplash.com/photo-1578632767115-351597cf2477?w=800&auto=format&fit=crop&q=80','Chugong','DUBU (REDICE Studio)','completed','manhwa',2018,1958,4.4,1420,'Dushanba','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(2,'jujutsu-kaisen','Sehrli Jang (Jujutsu Kaisen)','呪術廻戦','Yuji Itadori g''ayritabiiy jismoniy kuchga ega oddiy maktab o''quvchisi. Bir kuni u do''stlarini la''natlangan ruhlardan qutqarish uchun afsonaviy la''nat Sukunaning barmog''ini yutib yuboradi va la''natlar dunyosiga qadam qo''yadi.','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','Gege Akutami','Gege Akutami','ongoing','manga',2018,9833,4.8,88,'Seshanba','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(3,'attack-on-titan','Titanlar Hujumi (Attack on Titan)','進撃の巨人','Insoniyat qonxo''r bahaybat gigantlardan himoyalanish uchun uch qavatli ulkan devorlar ortida yashashga majbur. Eren Yeger onasining titan tomonidan halok bo''lishiga guvoh bo''lgach, barcha titanlarni yo''q qilishga qasamyod qiladi.','https://images.unsplash.com/photo-1534447677768-be436bb09401?w=800&auto=format&fit=crop&q=80','Hajime Isayama','Hajime Isayama','completed','manga',2009,18203,4.9,195,'Chorshanba','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(4,'black-clover','Qora Klever (Black Clover)','ブラッククローバー','Sehr dunyosida bir tomchi ham sehrli quvvatsiz tug''ilgan Asta va uning iste''dodli do''sti Yuno Sehrgarlar Qiroli bo''lish uchun bellashadilar. Asta anti-sehr qilichlariga ega besh bargli Klever grimuari egasiga aylanadi.','https://images.unsplash.com/photo-1563089145-599997674d42?w=800&auto=format&fit=crop&q=80','Yūki Tabata','Yūki Tabata','ongoing','manga',2015,6410,4.7,32,'Payshanba','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(5,'omniscient-reader','Hamma Narsani Biluvchi O''quvchi (Omniscient Reader)','전지적 독자 시점','Kim Dokja 10 yil davomida hech kim o''qimagan ''Vayron bo''lgan dunyoda omon qolishning 3 usuli'' nomli romanning yagona sadoqatli kitobxoni edi. Epilog chiqqan kuni roman voqealari haqiqiy hayotda sodir bo''la boshlaydi...','https://images.unsplash.com/photo-1569003339405-ea396a5a8a90?w=800&auto=format&fit=crop&q=80','sing N song','Sleepy-C','ongoing','manhwa',2020,22400,4.95,84,'Juma','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(6,'demon-slayer','Iblislar Qotili (Demon Slayer: Kimetsu no Yaiba)','鬼滅の刃','Tanjiro Kamado mehnatkash bola bo''lib, tog''da ko''mir sotish bilan oilasini boqardi. Bir kuni uyiga qaytib, butun oilasi qotillik qurboni bo''lganini, singlisi Nezuko esa iblisga aylanganini ko''radi.','https://images.unsplash.com/photo-1618336753974-aae8e04506aa?w=800&auto=format&fit=crop&q=80','Koyoharu Gotouge','Koyoharu Gotouge','completed','manga',2016,28900,4.88,110,'Shanba','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(7,'chainsaw-man','Benzopila Odam (Chainsaw Man)','チェンソーマン','Dendzi otasining ulkan qarzlarini to''lash uchun iblis iti Pochita bilan birga iblislar ovchisi bo''lib ishlaydi. Xiyonatga uchrab o''ldirilgach, Pochita uning yuragiga aylanadi va Dendzi Benzopila Odamga aylanadi.','https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?w=800&auto=format&fit=crop&q=80','Tatsuki Fujimoto','Tatsuki Fujimoto','ongoing','manga',2018,19500,4.85,67,'Seshanba','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(8,'one-piece','Van Pis (One Piece)','ワンピース','Qaroqchilar qiroli Gol D. Rodjer o''limidan oldin o''zining afsonaviy boyligi ''One Piece'' mavjudligini e''lon qiladi. Monkey D. Luffy Rezina-Rezina mevasini yeb elastik odamga aylanadi va o''z jamoasi bilan Qaroqchilar Qiroli bo''lish uchun Buyuk Yo''l sari suzadi.','https://images.unsplash.com/photo-1541701494587-cb58502866ab?w=800&auto=format&fit=crop&q=80','Eiichiro Oda','Eiichiro Oda','ongoing','manga',1997,45000,4.96,240,'Yakshanba','2026-10-14 12:16:31','2026-10-14 12:16:31');
INSERT INTO manga VALUES(9,'qilich-qiroli','Qilich qiroli','이계 검왕 생존기 (Survival Story of a Sword King)','Boshqa dunyoga tushib qolgan yigitning omon qolish va qilich qiroliga aylanish yo‘li.','https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?w=800&auto=format&fit=crop&q=80','YKB, Soon-Q','Kwon Soon-kyu','ongoing','manhwa',2019,2181,4.0,512,'Dushanba','2026-10-14 12:40:48','2026-10-14 12:40:48');
INSERT INTO manga VALUES(10,'gertsogning-kenja-ogli','Gertsogning qayta tug''ilgan kenja o''g''li — qotil','Duke''s Youngest Son',unistr('Imperiyaning eng buyuk qotili Kian Vert, umri bo''yi soya kabi ko''r-ko''rona ergashib yurgan akasining xiyonatidan so''ng, bir zumda halokatli o''lim topadi.\u000a\u000aBiroq u ko''zini ochganida, o''zining yoshlik yillariga, Gertsog xonadonining kenja o''g''li sifatida qayta tug''ilganini ko''radi. Endi uning yangi hayotdagi yagona maqsadi — qasos olish va oilaning haqiqiy himoyachisiga aylanishdir!'),'https://images.unsplash.com/photo-1569003339405-ea396a5a8a90?w=800&auto=format&fit=crop&q=80','Manga Complex','Studio Redice','ongoing','manhwa',2024,1071,4.8,2,'Chorshanba','2026-10-14 12:40:48','2026-10-14 12:40:48');
INSERT INTO manga VALUES(11,'qilich-ustasining-kenja-ogli','Qilich ustasining kenja o''g''li','Swordmaster''s Youngest Son','Runakandel xonadonining haydalgan o‘g‘li Qora Qilich Tangrisi bilan o‘tmishga qaytadi.','https://images.unsplash.com/photo-1618336753974-aae8e04506aa?w=800&auto=format&fit=crop&q=80','AZI','COBY','ongoing','manhwa',2022,4564,4.4,670,'Payshanba','2026-10-14 12:40:48','2026-10-14 12:40:48');
INSERT INTO manga VALUES(12,'chegara-bilmas-sehrgar','Chegara bilmas sehrgar','Infinite Mage','Cheksizlik nazariyasini kashf etgan yosh sehrgarning akademiyadagi yuksalishi.','https://images.unsplash.com/photo-1563089145-599997674d42?w=800&auto=format&fit=crop&q=80','Kim Chi-woo','KIRIN','ongoing','manhwa',2022,3890,4.4,480,'Juma','2026-10-14 12:40:48','2026-10-14 12:40:48');
INSERT INTO manga VALUES(13,'beginning-after-the-end','Oxiridan keyingi boshlanish','The Beginning After the End','Buyuk qirol Grey boshqa sehrli dunyoda yangidan hayot boshlaydi.','https://images.unsplash.com/photo-1534447677768-be436bb09401?w=800&auto=format&fit=crop&q=80','TurtleMe','Fuyuki23','ongoing','comic',2018,8900,5.0,1890,'Shanba','2026-10-14 12:40:48','2026-10-14 12:40:48');
INSERT INTO manga VALUES(14,'ilohiy-iblis-yuksalishi','Ilohiy iblis yuksalishi',NULL,'Qadimiy qonli iblislar kultining eng yosh rahbari taxtga qaytadi.','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80','TopManga Studio','Art Studio','ongoing','manhwa',2025,1420,5.0,50,'Dushanba','2026-10-14 15:18:41','2026-10-14 15:18:41');
