INSERT INTO manga VALUES(18,'oyinda-vaxshiy-sifatida-omon-qolish','O''yinda vaxshiy sifatida omon qolish',NULL,'Eng qiyin o‘yinga tushib qolib, vaxshiy bo‘lib omon qolish.','https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=800&auto=format&fit=crop&q=80','TopManga Studio','Art Studio','ongoing','manhwa',2023,2600,4.9,50,'Dushanba','2026-10-14 15:18:41','2026-10-14 15:18:41');
